package net.officefloor.hq.app.search;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/search")
public class TreeSearchController {

    private final TreeSearchService service;

    public TreeSearchController(TreeSearchService service) {
        this.service = service;
    }

    /** The people on the sheet and the other sheets of its tree whose name or an alias contains the
     *  text, case ignored (blank finds everyone). */
    @GetMapping
    public List<TreeSearchService.Found> search(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestParam(defaultValue = "") @Size(max = 200) String name) {
        return service.search(sheetId.trim(), name);
    }
}
package net.officefloor.hq.app.search;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGradeService;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Finds people by name or alias across a sheet and the other sheets of its tree. */
@Service
public class TreeSearchService {

    /** A person found: the sheet they are on, their name with the grade in force on that sheet's today,
     *  as "<name> (<grade>)", and their due-total there ("n/a" for none). */
    public record Found(String sheetId, String name, String dueTotal) {
    }

    private final PersonRepository people;
    private final PersonService personService;
    private final RollupService rollups;
    private final SheetService sheets;
    private final PersonGradeService grades;

    public TreeSearchService(PersonRepository people, PersonService personService, RollupService rollups,
            SheetService sheets, PersonGradeService grades) {
        this.people = people;
        this.personService = personService;
        this.rollups = rollups;
        this.sheets = sheets;
        this.grades = grades;
    }

    /** Every person whose name or an alias contains the text, case ignored: the sheet's own in list
     *  order first, then those of the other sheets of its tree by sheet id. */
    @Transactional(readOnly = true)
    public List<Found> search(String sheetId, String text) {
        String needle = text.toLowerCase(Locale.ROOT);
        List<String> others = new ArrayList<>(sheets.tree(sheetId));
        others.sort(null);
        List<String> order = new ArrayList<>(List.of(sheetId));
        order.addAll(others);
        List<Found> found = new ArrayList<>();
        for (String sheet : order) {
            Map<Long, List<String>> aliases = personService.aliases(sheet, null);
            Map<Long, String> dues = rollups.dueTotals(sheet);
            LocalDate today = sheets.today(sheet);
            for (Person person : people.findBySheetIdOrderByIdAsc(sheet)) {
                if (contains(person.getName(), needle) || aliases.getOrDefault(person.getId(), List.of()).stream()
                        .anyMatch(alias -> contains(alias, needle))) {
                    found.add(new Found(sheet, labelled(person, today), dues.getOrDefault(person.getId(), "n/a")));
                }
            }
        }
        return found;
    }

    /** The person's name with the grade in force on the date: "<name> (<grade>)". */
    private String labelled(Person person, LocalDate date) {
        return person.getName() + " (" + grades.gradeOn(person.getId(), date) + ")";
    }

    private static boolean contains(String value, String needle) {
        return value.toLowerCase(Locale.ROOT).contains(needle);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    /** The sheet's claims, newest listed first. */
    List<Claim> findBySheetIdOrderByListedDesc(String sheetId);

    /** A person's claims, newest listed first. */
    List<Claim> findBySheetIdAndPersonIdOrderByListedDesc(String sheetId, Long personId);

    /** A person's claim by its number on the sheet. */
    Optional<Claim> findBySheetIdAndPersonIdAndNumber(String sheetId, Long personId, String number);

    /** The numbers given on the sheet's claims. */
    @Query("select c.number from Claim c where c.sheetId = :sheetId and c.number is not null")
    List<String> numbers(@Param("sheetId") String sheetId);

    /** The numbers given up on the sheet by re-dated claims: never given again. */
    @Query(value = "SELECT claim_number FROM retired_claim_number WHERE sheet_id = :sheetId", nativeQuery = true)
    List<String> retiredNumbers(@Param("sheetId") String sheetId);

    /** Give up a claim number on the sheet for good. */
    @Modifying(flushAutomatically = true)
    @Query(value = "MERGE INTO retired_claim_number (sheet_id, claim_number) KEY (sheet_id, claim_number) VALUES (:sheetId, :number)",
            nativeQuery = true)
    void retireNumber(@Param("sheetId") String sheetId, @Param("number") String number);

    /** List a claim anew: it becomes the newest under its person. */
    @Modifying(flushAutomatically = true)
    @Query(value = "UPDATE claim SET listed = NEXT VALUE FOR claim_listed_seq WHERE id = :id", nativeQuery = true)
    void relist(@Param("id") Long id);

    /** Mark the claims as settled by a settle batch. */
    @Modifying(flushAutomatically = true, clearAutomatically = true)
    @Query("update Claim c set c.batch = :batch where c.id in :ids")
    void markBatch(@Param("ids") List<Long> ids, @Param("batch") Long batch);

    /** Release every editor's lock on the sheet's claims. */
    @Modifying(flushAutomatically = true)
    @Query("update Claim c set c.lockedBy = null where c.sheetId = :sheetId and c.lockedBy is not null")
    int releaseLocks(@Param("sheetId") String sheetId);

    /** Whether a claim on the sheet other than the given one (null: any) carries the reference key. */
    @Query("select count(c) > 0 from Claim c where c.sheetId = :sheetId and c.refKey = :refKey"
            + " and (:id is null or c.id <> :id)")
    boolean refInUse(@Param("sheetId") String sheetId, @Param("refKey") String refKey, @Param("id") Long id);

    /** Every tag ever used on the sheet's claims, sorted. */
    @Query(value = "SELECT tag FROM sheet_tag WHERE sheet_id = :sheetId ORDER BY tag", nativeQuery = true)
    List<String> tagsUsed(@Param("sheetId") String sheetId);

    /** Keep a tag on the sheet's list of the tags ever used. */
    @Modifying(flushAutomatically = true)
    @Query(value = "MERGE INTO sheet_tag (sheet_id, tag) KEY (sheet_id, tag) VALUES (:sheetId, :tag)",
            nativeQuery = true)
    void useTag(@Param("sheetId") String sheetId, @Param("tag") String tag);

    Optional<Claim> findByIdAndSheetIdAndPersonId(Long id, String sheetId, Long personId);

    /** How many of a person's claims due by a day between two dates (inclusive) are OPEN or PENDING. */
    @Query("select count(c) from Claim c where c.sheetId = :sheetId and c.personId = :personId"
            + " and c.status in (net.officefloor.hq.app.claim.ClaimStatus.OPEN,"
            + " net.officefloor.hq.app.claim.ClaimStatus.PENDING)"
            + " and c.dueBy >= :from and c.dueBy <= :to")
    long countOpenDueBetween(@Param("sheetId") String sheetId, @Param("personId") Long personId,
            @Param("from") LocalDate from, @Param("to") LocalDate to);
}
package net.officefloor.hq.app.person;

import java.util.Collection;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface PersonRepository extends JpaRepository<Person, Long> {

    /** The sheet's people in list order (by position); a person merged into another has left it. */
    @Query("select p from Person p where p.sheetId = :sheetId and p.mergedInto is null order by p.position, p.id")
    List<Person> findBySheetIdOrderByIdAsc(String sheetId);

    /** Everyone ever added to the sheet in list order (by position), those since merged into another
     *  included: a past day's view shows the people who were on the sheet then. */
    @Query("select p from Person p where p.sheetId = :sheetId order by p.position, p.id")
    List<Person> findEverBySheetId(String sheetId);

    /** The person on the sheet; a person merged into another has left it. */
    @Query("select p from Person p where p.id = :id and p.sheetId = :sheetId and p.mergedInto is null")
    Optional<Person> findByIdAndSheetId(Long id, String sheetId);

    /** The sheet's person with this name or alias, ignoring case; a person merged into another has left it. */
    @Query("select p from Person p where p.sheetId = :sheetId and p.mergedInto is null and (lower(p.name) = lower(:name)"
            + " or exists (select a from PersonAlias a where a.personId = p.id and a.aliasKey = lower(:name)))")
    Optional<Person> findByName(String sheetId, String name);

    /** Whether another person on the sheet (not {@code exceptId}) has this name, ignoring case. */
    @Query("select count(p) > 0 from Person p where p.sheetId = :sheetId and lower(p.name) = lower(:name)"
            + " and (:exceptId is null or p.id <> :exceptId)")
    boolean nameInUse(String sheetId, String name, Long exceptId);

    /** Whether anyone on any of the sheets has this name, ignoring case. */
    @Query("select count(p) > 0 from Person p where p.sheetId in :sheetIds and lower(p.name) = lower(:name)")
    boolean nameInUseOn(Collection<String> sheetIds, String name);

    /** The names on any of the sheets, lower-cased. */
    @Query("select lower(p.name) from Person p where p.sheetId in :sheetIds")
    List<String> nameKeysOn(Collection<String> sheetIds);

    /** Whether another person on the sheet (not {@code exceptId}) has this contact. */
    @Query("select count(p) > 0 from Person p where p.sheetId = :sheetId and p.contact = :contact"
            + " and (:exceptId is null or p.id <> :exceptId)")
    boolean contactInUse(String sheetId, String contact, Long exceptId);
}
package net.officefloor.hq.app.claim;

/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; an OPEN claim a clerk settles above
 *  the clerk limit is PENDING until a steward approves it (SETTLED) or rejects it (OPEN again); a
 *  DRAFT, OPEN or PENDING claim can be VOID, and a steward may void a SETTLED one within 7 days of
 *  its settlement. A DRAFT can be DELETED, counting nowhere, and restored to a DRAFT on the sheet's
 *  today it was deleted. A claim whose due is above the review threshold goes to REVIEW when opened,
 *  counting nowhere until a steward reviews it (OPEN); a REVIEW claim can be VOID. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** Whether the claim counts toward what is claimed and due. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether the claim is open: OPEN, or PENDING an approval. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** Whether a claim in this status may be moved to another person: a SETTLED or VOID one cannot. */
    public boolean canReassign() {
        return this == DRAFT || this == OPEN || this == PENDING;
    }

    /** Whether a claim in this status may be opened, settled or voided to the given one; a PENDING
     *  claim leaves PENDING only by being approved, rejected or voided. */
    public boolean canMoveTo(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == REVIEW;
            case PENDING, DRAFT, DELETED, REVIEW -> false;
        };
    }
}
